execution.command_template:
printf '%s\x00%s\x00%s\x00%s\x00%s\x00%s\x00%s\x00%s\x00%s' '{{target}}' '{{action}}' '{{plan}}' '{{failed_task}}' '{{tried}}' '{{replacement_tasks}}' '{{content}}' '{{task}}' '{{phase}}' | python3 -c "
import sys, re
data = sys.stdin.read()
parts = data.split('\x00')
target = parts[0] if len(parts) > 0 else ''
action = parts[1] if len(parts) > 1 else ''
plan = parts[2] if len(parts) > 2 else ''
failed_task = parts[3] if len(parts) > 3 else ''
tried = parts[4] if len(parts) > 4 else ''
replacement_tasks = parts[5] if len(parts) > 5 else ''
content = parts[6] if len(parts) > 6 else ''
task = parts[7] if len(parts) > 7 else ''
phase = parts[8] if len(parts) > 8 else ''
if target == 'findings':
    try:
        lines = open('todos.md').readlines()
    except FileNotFoundError:
        print('todos.md not found', file=sys.stderr)
        sys.exit(1)
    findings_idx = None
    for i, line in enumerate(lines):
        if line.strip() == '## Findings':
            findings_idx = i
            break
    if findings_idx is None:
        lines.append('## Findings\n')
        lines.append('- ' + content.strip() + '\n')
    else:
        lines.insert(findings_idx + 1, '- ' + content.strip() + '\n')
    open('todos.md', 'w').writelines(lines)
    print('Finding recorded.')
elif target == 'plan':
    if action == 'create':
        open('todos.md', 'w').write(plan.strip() + '\n\n## Findings\n\n## Archive\n')
        print('Plan created.')
    elif action == 'read':
        try:
            print(open('todos.md').read(), end='')
        except FileNotFoundError:
            print('todos.md not found', file=sys.stderr)
            sys.exit(1)
    elif action == 'complete':
        try:
            lines = open('todos.md').readlines()
        except FileNotFoundError:
            print('todos.md not found', file=sys.stderr)
            sys.exit(1)
        target_task = task.strip()
        idx = None
        for i, line in enumerate(lines):
            if line.strip().startswith('- [ ]') and target_task in line:
                idx = i
                break
        if idx is None:
            print('Task not found: ' + target_task, file=sys.stderr)
            sys.exit(1)
        lines[idx] = lines[idx].replace('- [ ]', '- [x]', 1)
        open('todos.md', 'w').writelines(lines)
        print('Task marked complete.')
    elif action == 'archive':
        try:
            lines = open('todos.md').readlines()
        except FileNotFoundError:
            print('todos.md not found', file=sys.stderr)
            sys.exit(1)
        phase_heading = phase.strip()
        active_end = len(lines)
        for i, line in enumerate(lines):
            if line.strip() in ('## Findings', '## Archive'):
                active_end = i
                break
        start = None
        for i in range(active_end):
            if lines[i].strip() == phase_heading:
                start = i
                break
        if start is None:
            print('Phase not found: ' + phase_heading, file=sys.stderr)
            sys.exit(1)
        end = active_end
        for i in range(start + 1, active_end):
            if lines[i].startswith('## '):
                end = i
                break
        phase_block = lines[start:end]
        lines = lines[:start] + lines[end:]
        archive_idx = None
        for i, line in enumerate(lines):
            if line.strip() == '## Archive':
                archive_idx = i
                break
        if archive_idx is not None:
            archive_end = len(lines)
            for i in range(archive_idx + 1, len(lines)):
                if lines[i].startswith('## '):
                    archive_end = i
                    break
            lines = lines[:archive_end] + phase_block + lines[archive_end:]
        else:
            lines.append('## Archive\n')
            lines.extend(phase_block)
        open('todos.md', 'w').writelines(lines)
        print('Phase archived.')
    elif action == 'revise':
        try:
            lines = open('todos.md').readlines()
        except FileNotFoundError:
            print('todos.md not found', file=sys.stderr)
            sys.exit(1)
        target_task = failed_task.strip()
        idx = None
        for i, line in enumerate(lines):
            if line.strip().startswith('- [ ]') and target_task in line:
                idx = i
                break
        if idx is None:
            print('Task not found: ' + target_task, file=sys.stderr)
            sys.exit(1)
        task_text = re.sub(r'^-\s*\[.\]\s*', '', lines[idx].strip())
        new_lines = []
        for t in replacement_tasks.strip().split('\n'):
            t = t.strip()
            if t:
                new_lines.append('- [ ] ' + t + '\n')
        new_lines.append('- \u2717 ' + task_text + ' \u2014 ' + tried.strip() + '\n')
        lines = lines[:idx] + new_lines + lines[idx+1:]
        open('todos.md', 'w').writelines(lines)
        print('Plan revised: ' + str(len(new_lines)-1) + ' replacement task(s) added, failure recorded.')
    else:
        print('Unknown action: ' + action, file=sys.stderr)
        sys.exit(1)
else:
    print('Unknown target: ' + target, file=sys.stderr)
    sys.exit(1)
"
